/**
 * Normaliza os nomes de chave de idioma para o padrão das combinações
 */
export function normalizeLanguageKey(key: string): string {
  const map: Record<string, string> = {
    palavras: 'palavras_afirmacao',
    palavras_afirmacao: 'palavras_afirmacao',
    servico: 'atos_servico',
    atos_servico: 'atos_servico',
    toque: 'toque_fisico',
    toque_fisico: 'toque_fisico',
    tempo: 'tempo_qualidade',
    tempo_qualidade: 'tempo_qualidade',
    presentes: 'presentes',
  };
  return map[key] || key;
}

/**
 * Substitui todas as variações de placeholders de nome do cônjuge pelo primeiro nome real
 */
export function replaceSpousePlaceholders(text: string, spouseFullName: string): string {
  if (!text) return '';
  const firstName = spouseFullName.trim().split(' ')[0] || 'Cônjuge';
  
  return text
    .replace(/\{\{\*{0,4}Nome\*{0,4}_Conjugue\*{0,4}\}\}/g, firstName)
    .replace(/\{\{Nome_Conjugue\}\}/gi, firstName)
    .replace(/\{\{Nome\}\}/gi, firstName)
    .replace(/\{\{Nome_Conjuge\}\}/gi, firstName);
}

/**
 * Retorna a combinação de casal formatada com o nome do cônjuge substituído
 */
export function getLoveLanguageCoupleCombination(
  idiomaPessoa: string,
  idiomaConjuge: string,
  spouseName: string = 'Cônjuge'
): LoveLanguageCoupleContent | null {
  const normPessoa = normalizeLanguageKey(idiomaPessoa);
  const normConjuge = normalizeLanguageKey(idiomaConjuge);

  const found = LOVE_LANGUAGE_COMBINATIONS.find(
    (c) => c.idioma_pessoa === normPessoa && c.idioma_conjuge === normConjuge
  );

  if (!found) return null;

  return {
    ...found,
    nivel_compatibilidade: replaceSpousePlaceholders(found.nivel_compatibilidade, spouseName),
    mapa_compatibilidade: replaceSpousePlaceholders(found.mapa_compatibilidade, spouseName),
    ponto_forte: replaceSpousePlaceholders(found.ponto_forte, spouseName),
    desafio_principal: replaceSpousePlaceholders(found.desafio_principal, spouseName),
    reflexao_relacional: replaceSpousePlaceholders(found.reflexao_relacional, spouseName),
    acoes_concretas: replaceSpousePlaceholders(found.acoes_concretas, spouseName),
    resumo: replaceSpousePlaceholders(found.resumo, spouseName),
  };
}
